function populateCharacterData() {
  const all_vars = getAllVariables();
  const data = _.get(all_vars, 'stat_data', {});

  const updateText = (id, path, fallback) => {
    const val = _.get(data, path, fallback);
    $(`#${id}`).text(val);
  };

  const updateProgress = (id, path) => {
    const val = _.get(data, path, 0);
    $(`#${id}-val`).text(val);
    $(`#${id}-bar`).css('width', val + '%');
  };

  updateProgress('stat-integrity', '个人状态.身份完整度');
  updateProgress('stat-risk', '个人状态.暴露风险');
  updateProgress('stat-fixer', '个人状态.固定器状态');
  updateProgress('stat-stress', '个人状态.心理压力');
  updateText('stat-visual', '个人状态.女性化视觉', '95');

  updateText('stat-fame', '社交评价.校园声望', '神秘美少女');
  updateText('stat-grace', '社交评价.优雅评分', '85');
  updateText('stat-club', '社交评价.社团状态', '待定');
  updateProgress('stat-social-stress', '社交评价.社交压力');

  updateProgress('bond-haruko', '情感羁绊.佐仓春子');
  updateProgress('bond-council', '情感羁绊.学生会');

  updateText('env-time', '环境信息.当前时段', '四月');
  updateText('env-loc', '环境信息.当前位置', '宿舍');
  updateText('env-study', '环境信息.学业表现', '优等生');
}
